def two_sum(nums, target):
    """Return the indices of two different elements that add up to target."""
    if nums is None or len(nums) < 2:
        return None
    seen = {}
    for j, num in enumerate(nums):
        need = target - num
        if need in seen:
            return [seen[need], j]
        if num not in seen:
            seen[num] = j
    # No two distinct elements add up to the target.
    return None

